#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;         string s;        cin >> s;         int balance = 0;        int ans = 0;         for (char c : s) {            if (c == '(') {                balance++;   // open bracket            } else {                balance--;   // close bracket            }             // invalid prefix            if (balance < 0) {                ans++;       // one move needed                balance = 0; // reset after fixing            }        }         cout << ans << "\n";    }     return 0;}